window.ScripturaLexicons.BDAG_PART_0257 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-01\" data-source=\"BDAG\" data-search=\"ὀξύς, εῖα, ύ adjetivo afiado; rápido; veloz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀξύς, εῖα, ύ</td><td>adjetivo</td><td>afiado; rápido; veloz</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-02\" data-source=\"BDAG\" data-search=\"ὀξυχολέω verbo irar-se facilmente; ser irritadiço BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀξυχολέω</td><td>verbo</td><td>irar-se facilmente; ser irritadiço</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-03\" data-source=\"BDAG\" data-search=\"ὀξυχολία, ας, ἡ substantivo feminino irritabilidade; mau temperamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀξυχολία, ας, ἡ</td><td>substantivo feminino</td><td>irritabilidade; mau temperamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-04\" data-source=\"BDAG\" data-search=\"ὀξύχολος, ον adjetivo irascível; de mau temperamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀξύχολος, ον</td><td>adjetivo</td><td>irascível; de mau temperamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-05\" data-source=\"BDAG\" data-search=\"ὀπή, ῆς, ἡ substantivo feminino abertura; buraco; fenda BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀπή, ῆς, ἡ</td><td>substantivo feminino</td><td>abertura; buraco; fenda</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-06\" data-source=\"BDAG\" data-search=\"ὄπισθεν advérbio/preposição atrás; depois; posteriormente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄπισθεν</td><td>advérbio/preposição</td><td>atrás; depois; posteriormente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-07\" data-source=\"BDAG\" data-search=\"ὀπίσω advérbio/preposição para trás; atrás; depois BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀπίσω</td><td>advérbio/preposição</td><td>para trás; atrás; depois</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-08\" data-source=\"BDAG\" data-search=\"ὁπλή, ῆς, ἡ substantivo feminino casco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁπλή, ῆς, ἡ</td><td>substantivo feminino</td><td>casco</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-09\" data-source=\"BDAG\" data-search=\"ὁπλίζω verbo equipar; armar; preparar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁπλίζω</td><td>verbo</td><td>equipar; armar; preparar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-10\" data-source=\"BDAG\" data-search=\"ὅπλον, ου, τό substantivo neutro instrumento; ferramenta; arma BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅπλον, ου, τό</td><td>substantivo neutro</td><td>instrumento; ferramenta; arma</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-11\" data-source=\"BDAG\" data-search=\"ὁπόθεν advérbio de onde; onde BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁπόθεν</td><td>advérbio</td><td>de onde; onde</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-12\" data-source=\"BDAG\" data-search=\"ὁποῖος, οία, οῖον pronome de que espécie; de que tipo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁποῖος, οία, οῖον</td><td>pronome</td><td>de que espécie; de que tipo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-13\" data-source=\"BDAG\" data-search=\"ὁπόσος, η, ον pronome interrogativo quanto; quão grande BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁπόσος, η, ον</td><td>pronome interrogativo</td><td>quanto; quão grande</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-14\" data-source=\"BDAG\" data-search=\"ὁπόταν partícula temporal sempre que; quando quer que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁπόταν</td><td>partícula temporal</td><td>sempre que; quando quer que</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-15\" data-source=\"BDAG\" data-search=\"ὁπότε partícula temporal quando BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁπότε</td><td>partícula temporal</td><td>quando</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-16\" data-source=\"BDAG\" data-search=\"ὅπου partícula de lugar onde; para onde; visto que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅπου</td><td>partícula de lugar</td><td>onde; para onde; visto que</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-17\" data-source=\"BDAG\" data-search=\"ὀπτάνομαι verbo aparecer; tornar-se visível BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀπτάνομαι</td><td>verbo</td><td>aparecer; tornar-se visível</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-18\" data-source=\"BDAG\" data-search=\"ὀπτασία, ας, ἡ substantivo feminino visão; aparição; transe BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀπτασία, ας, ἡ</td><td>substantivo feminino</td><td>visão; aparição; transe</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-19\" data-source=\"BDAG\" data-search=\"ὀπτάω verbo assar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀπτάω</td><td>verbo</td><td>assar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0257-20\" data-source=\"BDAG\" data-search=\"ὀπτός, ή, όν adjetivo assado; tostado; grelhado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀπτός, ή, όν</td><td>adjetivo</td><td>assado; tostado; grelhado</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0257-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀξύς, εῖα, ύ</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀξύς</span>, <span class=\"greek\">εῖα</span>, <span class=\"greek\">ύ</span>. ① Relativo a ter um gume apto a cortar, afiado, cortante (assim Hom. e outros; LXX; TestJud 1:4; JosAs 16:13; EpArist 60 e 276; Philo; Jos., Ant. 14, 422; Just., D. 127, 2 <span class=\"greek\">ὀξὺ</span> <span class=\"greek\">ὁρῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὀξὺ</span> <span class=\"greek\">ἀκούων</span> [de Deus]; Mel., P. 78, 522 <span class=\"greek\">ἥλους</span> <span class=\"greek\">ὀξεῖς</span>): <span class=\"greek\">ῥομφαία</span>, espada afiada (Ezk 5:1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:16</a>; 2:12; 19:15. <span class=\"greek\">δρέπανον</span>, foice afiada, 14:14, 17f. ② Relativo à rapidez de movimento, rápido, veloz, ligeiro (trágicos, Hdt. e outros; POxy 900, 7; 1412, 18 <span class=\"greek\">ὀξέως</span>; LXX, Philo; Jos., Ant. 5, 261); com infinitivo aoristo (Ael. Aristid. 34 p. 665 D.: <span class=\"greek\">τὰ</span> <span class=\"greek\">βέλτιστα</span> <span class=\"greek\">πρᾶξαι</span> <span class=\"greek\">ὀ</span>.), num aforismo de grande precisão expressiva: <span class=\"greek\">ὀξεῖς</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">πόδες</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἐκχέαι</span> <span class=\"greek\">αἷμα</span>, seus pés são rápidos (= «afiados» quanto aos pés) para derramar sangue, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:15</a> (Ps 13:3).—B. 1034; 1069. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀξυχολέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀξυχολέω</span> (<span class=\"greek\">ὄξυχολο</span>), particípio do 1º aoristo <span class=\"greek\">ὀξυχολήσας</span>, ter mau temperamento, ser irritadiço, irar-se facilmente: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄνθρ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ὀξυχολήσας</span>, a pessoa que se deixa dominar facilmente pela ira, Hm 10, 2, 3.—DELG s.v. <span class=\"greek\">χόλο</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀξυχολία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀξυχολία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὀξύχολος</span>; Cat. Cod. Astr. XII 143, 16; escritores cristãos), irritabilidade, mau humor, índole colérica, Hm 5, 1, 3; 6f; 5, 2, 1; 4; 10, 2, 3. <span class=\"greek\">ἀπέχεσθαι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀξ</span>., abster-se da irritabilidade, 5, 2, 8a; <span class=\"greek\">ἀντιστῆναι</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὀξ</span>., resistir à irritabilidade, 5, 2, 8b. <span class=\"greek\">ὀξ</span>. <span class=\"greek\">προσπίπτει</span> <span class=\"greek\">τινί</span>, a irritabilidade acomete alguém, 6, 2, 5. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ὀξ</span>. <span class=\"greek\">τις</span> <span class=\"greek\">προσέλθῃ</span>, se alguma irritabilidade sobrevier, 5, 1, 3. É chamada irmã de <span class=\"greek\">λύπη</span> e de <span class=\"greek\">διψυχία</span>, 10, 1, 1f. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀξ</span>. <span class=\"greek\">λυπεῖ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span>, a irritabilidade entristece o Espírito, 10, 2, 4. Personificada entre os vícios, Hs 9, 15, 3.—DELG s.v. <span class=\"greek\">χόλο</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀξύχολος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀξύχολος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ὀξύς</span>, <span class=\"greek\">χόλος</span>, «fel, ira amarga»; o advérbio ocorre em Soph., Ant. 955, o adjetivo em Solon 1, 26 Diehl 3; Anth. Pal. 9, 127, 4), relativo a alguém que facilmente se entrega à ira, irritadiço, irascível, de mau temperamento; com <span class=\"greek\">πικρός</span> e <span class=\"greek\">ἄφρων</span>, Hm 6, 2, 4. Substantivado (cf. Lucian, Fugit. 19 <span class=\"greek\">τὸ</span> <span class=\"greek\">ὀξύχολον</span> = <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀξυχολία</span>): <span class=\"greek\">ὁ</span> <span class=\"greek\">ὀξ</span>., o irascível, pessoa de mau temperamento, 5, 2, 7; Hs 6, 5, 5.—DELG s.v. <span class=\"greek\">χόλο</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀπή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀπή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Aristoph. e outros; LXX; TestSol 6:4 D; Philo; Jos., Ant. 9, 163), abertura, buraco, fenda; com genitivo (Herodas 2, 42; Ex 33:22 <span class=\"greek\">ὀπ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πέτρας</span>; Ob 3): <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> (Alciphron 2, 1, 2), buracos na terra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.38\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:38</a>. Uso absoluto (Aesop, Fab. 353 P.=Babr. 112 Cr., acerca da toca de um rato), abertura de onde brota uma nascente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:11</a>. B. 909.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄπισθεν</h1><div class=\"entry-meta\"><span>advérbio/preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄπισθεν</span>, advérbio (Hom. e outros [<span class=\"greek\">ὄπιθεν</span>; ver Kühner-Bl. II 309f; Schwyzer I 628; cf. advérbio <span class=\"greek\">ὀπίσω</span>]; inscrições, papiros, LXX, pseudoepígrafos, Joseph.; Ath. 20, 1). ① Relativo a uma extensão que fica atrás, de trás, para trás, depois. ⓐ Como advérbio (Appian, Syr. 24 §119; 63 §334, Bell. Civ. 4, 55 §239), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:44</a>. ⓑ Funcionando como preposição com genitivo (Hom. e outros; SIG 46, 65; 969, 5f; PGM 4, 1230 <span class=\"greek\">ὄπισθεν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">σταθείς</span>; LXX): <span class=\"greek\">α</span>. De lugar, atrás de alguém (Menand., Kolax 47 S. <span class=\"greek\">ὄπισθ</span>’ <span class=\"greek\">ἐβάδιζέ</span> <span class=\"greek\">μου</span>; B-D-F § 215, 1; Rob. 645): <span class=\"greek\">κράζειν</span> <span class=\"greek\">ὄπ</span>. <span class=\"greek\">τινος</span>, gritar atrás de alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:23</a>. <span class=\"greek\">ἤκουσα</span> … <span class=\"greek\">ὄπ</span>. <span class=\"greek\">μου</span>, ouvi atrás de mim, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:10</a>, variante de leitura. <span class=\"greek\">φέρειν</span> (<span class=\"greek\">τι</span>) <span class=\"greek\">ὄπ</span>. <span class=\"greek\">τινος</span>, carregar (algo) atrás de alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:26</a>. <span class=\"greek\">β</span>. De tempo, depois de alguém ou algo: <span class=\"greek\">ὄπισθεν</span> <span class=\"greek\">αὐτῶν</span>, depois deles, 4:4, variante de leitura (cf. Da 7:24). ② Relativo à posição na parte posterior de um objeto, atrás, em oposição a <span class=\"greek\">ἔμπροσθεν</span> (ver esse verbete, 2, e cf. Hes., Shield 132f <span class=\"greek\">πρόσθεν</span> … <span class=\"greek\">ὄπισθε</span>; Jos., Ant. 13, 30 <span class=\"greek\">ἔμπροσθεν</span> <span class=\"greek\">αὐτῶν</span> … <span class=\"greek\">ὄπισθεν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:6</a>. De um rolo escrito: <span class=\"greek\">ἔσωθεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὄπισθεν</span>, por dentro e no verso, isto é, no anverso e reverso, 5:1 (cf. PTebt 58, anverso, 37 [III a.C.] <span class=\"greek\">τἀπίλοιπα</span> <span class=\"greek\">ὀπείσωι</span> = «o restante está no verso»; óstraco da coleção Deissmann em PMeyer 107ff, nº 61, 15 [III a.C.] <span class=\"greek\">ὀπίσω</span> = «vire»; PGM 12, 267; 276). O autor do Apocalipse evidentemente recorre a Ezk 2:10 para expressar plenitude de comunicação. Sobre o tipo de rolo <span class=\"greek\">ὀπισθόγραφον</span>, ver Pliny, Ep. 3, 5, 17; outros exemplos em Wetstein; RCharles, comentário ad loc. ③ Relativo a algo que vem depois no tempo, posteriormente (Hom. e outros), 4:4 (diferentemente, Da 7:24).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀπίσω</h1><div class=\"entry-meta\"><span>advérbio/preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀπίσω</span>, advérbio (Hom. [<span class=\"greek\">ὀπίσσω</span>] e posteriores). ① Marcador de posição na parte de trás de alguma coisa, atrás. ⓐ Como advérbio. <span class=\"greek\">α</span>. Em resposta à pergunta «onde?», atrás; em nossa literatura, só com artigo <span class=\"greek\">τὸ</span> <span class=\"greek\">ὀπ</span>.: <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὐπίσω</span>, para trás (Pla., Phdr. 254b, Rep. 528a; Diod S 1, 32, 5; Lucian, De Merc. Cond. 21; Dionys. Byz. 53 p. 21, 16; Jos., Ant. 7, 15): <span class=\"greek\">ἀφορμᾶν</span>, partir para trás, 1 Cl 25:4. Sobretudo no plural <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀπ</span>., o que fica para trás (<span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀπίσω</span>: PPetr. III, 23 [246 a.C.]; BGU 1002, 16), em imagem de uma corrida, o trecho do percurso já vencido, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:13</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀπ</span>. (1 Macc 9:47; Philo, Leg. All. 2, 99 [= Gen 49:17]): <span class=\"greek\">ἀπέρχεσθαι</span>, recuar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:6</a>; figuradamente, retirar-se, 6:66. <span class=\"greek\">στρέφεσθαι</span>, voltar-se para trás, virar-se, 20:14; GJs 15:5 (Antimachus Coloph. [V/IV a.C.], ed. BWyss ’36, Fgm. 60 <span class=\"greek\">στρέφεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὐπίσω</span>; cf. Ps 113:3). Também <span class=\"greek\">ἐπιστρέφεσθαι</span>, Hv 4, 3, 7 (cf. 4 Km 20:10). <span class=\"greek\">ἐπιστρέφειν</span>, voltar (para casa), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:31</a>. <span class=\"greek\">βλέπειν</span>, olhar para trás (cf. Plut., Nic. 532 [14, 2] <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">βλ</span>.; Artem. 1, 36 p. 37, 23 <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">βλέπειν</span>; Gen 19:17, 26), em imagem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.62\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:62</a>. Lançar para trás = rejeitar, 1 Cl 35:8 (Ps 49:17). <span class=\"greek\">β</span>. Em resposta à pergunta «para onde?», para trás, atrás (Lucian, Dea Syr. 36; Appian, Maced. 18 §3, Mithrid. 104 §489; Polyaenus 7, 27, 1; Gen 24:5; 3 Km 18:37; Jos., Ant. 6, 15): <span class=\"greek\">στῆναι</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">παρὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πόδας</span> <span class=\"greek\">αὐτοῦ</span>, pôr-se em pé atrás dele, junto a seus pés, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:38</a>. <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span> <span class=\"greek\">ποιεῖν</span>, colocar as mãos atrás de si, MPol 14:1. ⓑ Funcionando como preposição com genitivo (POxy 43 B IV, 3 <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">Καπιτολείου</span>; LXX), atrás (OGI 56, 62 [237 a.C.] <span class=\"greek\">ταύτης</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">ὀπίσω</span> = «atrás desta»; Ps.-Lucian, Asin. 17; 29; Chion, Ep. 4, 3; SSol 2:9.—Gen 19:6): <span class=\"greek\">ἤκουσα</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">μου</span>, ouvi atrás de mim, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:10</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">σου</span>, Hs 9, 2, 7.—<span class=\"greek\">ὕπαγε</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">μου</span>, vai para trás de mim! sai da minha frente!, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:10</a>, variante de leitura; 16:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:33</a> (CDodd, JTS 5, ’54, 246f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:8</a>, variante de leitura (cf. 4 Km 9:19). Substantivado: <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">σου</span> <span class=\"greek\">ἰδεῖν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">δύνῃ</span>, não podes ver o que está atrás de ti, Hs 9, 2, 7 (ver 1a <span class=\"greek\">α</span>, final).—VHarlow, Jesus’ Jerusalem Expedition ’36, 20–37: <span class=\"greek\">Ὀπίσω</span> <span class=\"greek\">μου</span>, especialmente 31f. ② Marcador de posição atrás de uma entidade que vai à frente, após; funciona como preposição com genitivo. ⓐ De lugar, após (Ex 15:20; 2 Km 3:16; JosAs 26:7; 27:6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:14</a>. <span class=\"greek\">ὀπ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">γυναικός</span>, atrás da mulher, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:15</a>. <span class=\"greek\">ἔρχεσθαι</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">τινός</span>, vir atrás de alguém, segui-lo (ao mesmo tempo no sentido figurado de «ser adepto ou seguidor»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:34</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:23</a>; 14:27. Também <span class=\"greek\">ἀκολουθεῖν</span> (ver esse verbete 2; e Gulin s.v. <span class=\"greek\">μιμητής</span> a), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:34</a>. <span class=\"greek\">ἀπέρχεσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:19</a>. <span class=\"greek\">πορεύεσθαι</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">τινός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:8</a>. Os dois últimos verbos também se combinam com <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">τινός</span> em outra relação: <span class=\"greek\">ἀπέρχεσθαι</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἑτέρας</span>, ir atrás de carne estranha ou alheia, isto é, os humanos de Sodoma desejavam sexualmente seres de outra ordem, a saber, anjos (segundo En 12:4 e outros, o inverso ocorreu quando anjos visitaram mulheres terrenas), Jd 7. A passagem paralela <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:10</a>, por outro lado, apresenta <span class=\"greek\">ὀπ</span>. <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐπιθυμίᾳ</span> <span class=\"greek\">μιασμοῦ</span> <span class=\"greek\">πορεύεσθαι</span>, em que <span class=\"greek\">σάρξ</span> parece ser antes o poder do desejo contaminante, ao qual (<span class=\"greek\">σάρξ</span>) os pecadores juraram fidelidade. Cf. Hv 3, 7, 3.—<span class=\"greek\">δεῦτε</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">μου</span>, vinde após mim, segui-me (ver <span class=\"greek\">δεῦτε</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:17</a>. <span class=\"greek\">ἀποσπᾶν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">τινός</span> (ver <span class=\"greek\">ἀποσπάω</span> 2a), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:30</a>. <span class=\"greek\">ἀφιστάναι</span> <span class=\"greek\">λαὸν</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">αὐτοῦ</span> (ver <span class=\"greek\">ἀφίστημι</span> 1), 5:37. <span class=\"greek\">ἐκτρέπεσθαι</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σατανᾶ</span> (ver <span class=\"greek\">ἐκτρέπω</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:15</a> (cf. Ar. 3, 2 <span class=\"greek\">ἐπλανήθησαν</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">στοιχείων</span>; 7, 4). <span class=\"greek\">θαυμάζεσθαι</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">τινός</span> (ver <span class=\"greek\">θαυμάζω</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:3</a>. ⓑ De tempo, depois (3 Km 1:6, 24; Eccl 10:14): <span class=\"greek\">ἔρχεσθαι</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">τινός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:15</a>, 27, 30 (CLindeboom, «Die na mij komt, is voor mij geworden»: GereformTT 16, 1916, 438–46; diferentemente [«um seguidor meu»], KGrobel, JBL 60, ’41, 397–401).—DELG s.v. <span class=\"greek\">ὄπισθεν</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁπλή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁπλή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; LXX; EpArist 150), casco, inclusive o casco fendido dos bovinos (Hom. Hymns, Merc. 77; Hes., Works 491; Pind., Pyth. 4, 226; Hdt. 2, 71; SIG 1026, 19 [IV/III a.C.]): <span class=\"greek\">ἐκφέρειν</span> <span class=\"greek\">ὁπλάς</span>, desenvolver cascos, 1 Cl 52:2 (Ps 68:32).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁπλίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁπλίζω</span> (<span class=\"greek\">ὅπλον</span>), 1º aoristo médio <span class=\"greek\">ὡπλισάμην</span> (em geral «aprontar algo» ou «equipar com algo», frequentemente em contextos de preparação militar; Hom. e outros; Jer 52:25 Sym.; Jos., Vi. 45; SibOr 2, 119), preparar, sobretudo mediante equipamento, equipar, armar; na voz média, preparar-se ou equipar-se; em nossa literatura somente em sentido figurado, com <span class=\"greek\">τὶ</span>, com alguma coisa: <span class=\"greek\">τὴν</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">ἔννοιαν</span>, munir-se da mesma compreensão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:1</a> (cf. Soph., Electra 996 <span class=\"greek\">τοιοῦτον</span> <span class=\"greek\">θράσος</span> <span class=\"greek\">αὐτή</span> <span class=\"greek\">θ</span>’ <span class=\"greek\">ὁπλίζει</span> = «tu te armas de tamanha temeridade»; Anth. Pal. 5, 93, 1 <span class=\"greek\">ὥπλισμαι</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">Ἔρωτα</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">στέρνοισι</span> <span class=\"greek\">λογισμόν</span> = «armei-me contra Eros com a razão em torno do peito»; Jos., Ant. 6, 187 <span class=\"greek\">τ</span>. <span class=\"greek\">θεὸν</span> <span class=\"greek\">ὥπλισμαι</span>, Davi enfrenta Golias). A imagem militar não é tão evidente aqui (ver o artigo seguinte, 1) quanto na passagem posterior. Com dativo <span class=\"greek\">τινί</span>, com algo (Eur., Andr. 1118; X., Cyr. 6, 4, 4, com menção específica de armadura; Cornutus 31 p. 63, 17): <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὅπλοις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δικαιοσύνης</span>, com as armas da justiça, Pol 4:1. Aqui o dativo acompanhante estabelece uma metáfora militar.—DELG s.v. <span class=\"greek\">ὅπλον</span>. M-M. s.v. <span class=\"greek\">ὁπλίζομαι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅπλον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅπλον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (ver artigo precedente; Hom. e posteriores; inscrições, papiros, LXX; TestSol 8:6; TestLevi 5:3; EpArist, Philo, Joseph.; Tat. 31, 1; Ath. 35, 1). ① Qualquer instrumento usado para preparar ou deixar algo pronto, utensílio, ferramenta: <span class=\"greek\">ὅπλα</span> <span class=\"greek\">ἀδικίας</span>, instrumentos da injustiça, isto é, ferramentas para fazer o que é mau, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:13a</a> (cf. Aristot., Pol. 1253a). Oposto a <span class=\"greek\">ὅπλα</span> <span class=\"greek\">δικαιοσύνης</span>, versículo 13b. Mas o sentido 2 também é provável; ele ocorre em todas as outras passagens de nossa literatura, especificamente em Paulo. ② Instrumento concebido para equipar alguém para combate militar, arma. ⓐ Literalmente, no plural (Demetr.: 722 Fgm. 5 Jac. <span class=\"greek\">ὅπλα</span> <span class=\"greek\">εἶχον</span>; Jos., Vi. 99 <span class=\"greek\">ἧκον</span> <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ὅπλων</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:3</a>. Cavaleiros <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">συνήθων</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὅπλων</span>, com suas armas habituais, MPol 7:1. No singular: <span class=\"greek\">τίθησιν</span> <span class=\"greek\">Μωϋσῆς</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἓν</span> <span class=\"greek\">ὅπλον</span>, Moisés colocou um escudo (sentido já em Hdt.; Diod S 17, 21, 2; 17, 43, 9 [alternando com <span class=\"greek\">ἀσπίδες</span> 8]; 17, 57, 2; Sb 7247, 24 [296 d.C.]; TestLevi 5:3 <span class=\"greek\">ὅπλον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ῥομφαίαν</span>) sobre outro, para subir sobre eles e enxergar melhor o campo de batalha, 12:2. ⓑ Em imagem, no plural, acerca da vida do cristão como combate contra o mal: <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅπ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">στρατείας</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">σαρκικά</span>, as armas de nossa guerra não são materiais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:4</a>. <span class=\"greek\">ἐνδύσασθαι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅπ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">φωτός</span>, revestir-se das armas da luz, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:12</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅπ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">δικαιοσύνης</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δεξιὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀριστερά</span>, as armas da justiça para ataque e defesa (ver <span class=\"greek\">ἀριστερός</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:7</a>. <span class=\"greek\">ὁπλίζεσθαι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὅπλοις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δικαιοσύνης</span>, armar-se das armas da justiça, Pol 4:1 (ver <span class=\"greek\">ὁπλίζω</span>). Sobre o mau desejo: <span class=\"greek\">φοβουμένη</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅπ</span>. <span class=\"greek\">σου</span>, temendo tuas armas, isto é, aquelas do cristão equipado para o bom combate, Hm 12, 2, 4. Sobre o batismo: <span class=\"greek\">τὸ</span> <span class=\"greek\">βάπτισμα</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">μενέτω</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ὅπλα</span>, que vosso batismo permaneça como vossas armas («permaneça», em contraste com o desertor que abandona as armas), IPol 6:2. Sobre o próprio Cristo: <span class=\"greek\">ὅπλον</span> <span class=\"greek\">εὐδοκίας</span>, escudo do beneplácito (de Deus), AcPl Ha 8, 23 = Ox 1602, 34f//BMM anverso, 30.—B. 1383. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁπόθεν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁπόθεν</span>, advérbio de lugar (Hom. e outros; não na LXX; PPar I, 125 e 165 [IV d.C.]; Just.), onde, literalmente «de onde», Papias (3:2).—DELG s.v. <span class=\"greek\">πο</span>-. Frisk s.v. <span class=\"greek\">πόθεν</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁποῖος, οία, οῖον</h1><div class=\"entry-meta\"><span>pronome</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁποῖος</span>, <span class=\"greek\">οία</span>, <span class=\"greek\">οῖον</span> (Hom. e posteriores), pronome correlativo, de que espécie, que tipo; como <span class=\"greek\">τοιοῦτος</span>, <span class=\"greek\">ὁπ</span>. (X., Cyr. 1, 6, 36; Ael. Aristid. 45, 1 K.=8 p. 81 D.; IGR III, 89, 12–14 [69 d.C.]; Jos., Ant. 7, 385; Just., A I, 19, 5 e outros; Tat. 21, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:29</a>; cf. Hm 11:15. Usado como pronome em perguntas indiretas (Hom. e outros; ver B-D-F § 300, 1; Rob. 732; em pergunta direta, Tat. 32, 13): <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">ὁπ</span>. <span class=\"greek\">ἐστιν</span>, de que espécie é a obra (realizada por cada um), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:13</a>. <span class=\"greek\">ὁπ</span>. <span class=\"greek\">εἴσοδον</span> <span class=\"greek\">ἔσχομεν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span>, que tipo de acolhida tivemos entre vós, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:9</a>. <span class=\"greek\">ἐπελάθετο</span> <span class=\"greek\">ὁποῖος</span> <span class=\"greek\">ἦν</span>, esquece que espécie de pessoa é, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:24</a>. Quase equivalente ao relativo, 1 Cl 43:2. <span class=\"greek\">ὁποῖοί</span> <span class=\"greek\">ποτε</span> <span class=\"greek\">ἦσαν</span> <span class=\"greek\">οὐδέν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">διαφέρει</span>, não me importa que tipo de pessoas eles foram, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:6</a> (cf. Just., A I, 21, 4; ver B-D-F § 303; Rob. 732; VWeber, Erklärung von <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:6a</a>: Der Katholik 80, 1900, 481–99).—DELG s.v. <span class=\"greek\">πο</span>-. Frisk s.v. <span class=\"greek\">ποῖο</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁπόσος, η, ον</h1><div class=\"entry-meta\"><span>pronome interrogativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁπόσος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Hom. e outros; inscrições; PHal 1, 206; BGU 1074, 6; Jos., Ant. 16, 351; 17, 30; SibOr 3, 480; Just., A I, 23, 1; Ath., R. 23 p. 76, 31 <span class=\"greek\">πᾶν</span> <span class=\"greek\">ὁπόσον</span>), interrogativo referente ao grau da quantidade ou qualidade, quão grande, quanto; neutro <span class=\"greek\">ὁπόσον</span> (SIG 400, 18), quanto: <span class=\"greek\">ὁπ</span>. <span class=\"greek\">δίκαιός</span> <span class=\"greek\">ἐστιν</span>, quão justo ele é, GPt 8:28 (manuscrito: <span class=\"greek\">οτιποσον</span>).—DELG s.v. <span class=\"greek\">πο</span>-. Frisk s.v. <span class=\"greek\">πόσο</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁπόταν</h1><div class=\"entry-meta\"><span>partícula temporal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁπόταν</span>, partícula temporal (Pind. e posteriores [Hom. separa <span class=\"greek\">ὁπότ</span>’ <span class=\"greek\">ἄν</span>]; SIG 344, 75; papiros; Job 29:22; TestSol; SibOr 5, 464; Jos., Ant. 6, 166; 16, 387 e outros; Just., Tat., Mel.; Ath., R. 21 p. 74, 28 [todos apenas com subjuntivo]), sempre que, quando quer que: <span class=\"greek\">εἶτα</span>, <span class=\"greek\">ὁπόταν</span> <span class=\"greek\">καθεῖλεν</span>, então, sempre que ele abaixava (as mãos), 12:2 (cf. Mel., P. 11, 74 <span class=\"greek\">ὁπόταν</span> <span class=\"greek\">βούλεται</span>; ver também B-D-F § 381; Rob. 971; Reinhold p. 108).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁπότε</h1><div class=\"entry-meta\"><span>partícula temporal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁπότε</span>, partícula temporal (Hom. e posteriores), quando, com indicativo, referente a acontecimentos concretos no passado (Hom.; POxy 243, 10; PRyl 245, 3; Tob 7:11 Sin.; Just., D. 28, 5 e outros; Mel., P. 42, 287; Ath. 21, 4), 12:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:3</a>, variante de leitura (em lugar de <span class=\"greek\">ὅτε</span>).—B-D-F § 455, 1; Rob. 971.—DELG s.v. <span class=\"greek\">πο</span>-. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅπου</h1><div class=\"entry-meta\"><span>partícula de lugar</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅπου</span>, partícula de lugar (Hom. e posteriores), que também pode assumir significados causais e temporais. ① Marcador de uma posição no espaço, onde. ⓐ De um local específico no presente. <span class=\"greek\">α</span>. Usado em ligação com uma designação de lugar, seguido de indicativo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:19f</a>; 13:5; 28:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:4b</a>; 4:5; 9:48; 16:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:28</a>; 4:20, 46; 7:42 e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:8</a>; 20:10 (aqui o verbo é suprido pelo contexto). <span class=\"greek\">πρὸς</span> <span class=\"greek\">Καϊάφαν</span>, <span class=\"greek\">ὅπου</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">γραμματεῖς</span> <span class=\"greek\">συνήχθησαν</span>, até Caifás, isto é, à sua residência, onde os escribas se reuniram, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.57\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:57</a>. <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ὅπ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:13b</a>; <span class=\"greek\">οὗτοι</span> ... <span class=\"greek\">ὅπου</span> <span class=\"greek\">σπείρεται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span>, esses … nos quais (= em cujos corações) se semeia a palavra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:15</a>. Apontando para um <span class=\"greek\">ἐκεῖ</span> (Jos., C. Ap. 1, 32), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:34</a>; 17:37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:26</a>.—Não raro <span class=\"greek\">ὅπ</span>. se refere a um <span class=\"greek\">ἐκεῖ</span> omitido, mas facilmente subentendido: (<span class=\"greek\">ἐκεῖ</span>) <span class=\"greek\">ὅπ</span>., (ali) onde (Maximus Tyr. 31, 5b), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:24</a>, 26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:4a</a>; 13:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:8</a>; 14:3; 17:24; 20:12, 19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:13a</a>; (para lá) onde, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:40</a>; 6:55; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.62\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:62</a>; 7:34, 36; 11:32; 18:1.—Sobre o emprego pleonástico do pronome pessoal depois de <span class=\"greek\">ὅπου</span>, ver B-D-F § 297; Rob. 683; 722f: <span class=\"greek\">ὅπ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">γυνὴ</span> <span class=\"greek\">κάθηται</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:9</a>. Correspondência <span class=\"greek\">ὅπου</span> … <span class=\"greek\">ἐκεῖ</span> (<span class=\"hebrew\" dir=\"rtl\">שָׁם</span> ... <span class=\"hebrew\" dir=\"rtl\">אֲשֶׁר</span>), 12:6, 14. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:55</a>, variante de leitura. <span class=\"greek\">β</span>. <span class=\"greek\">ὅπ</span>. <span class=\"greek\">ἄν</span> com imperfeito exprime repetição no passado, sempre que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:56</a> (ver B-D-F § 367; Rob. 969; 972f). <span class=\"greek\">γ</span>. Emprega-se subjuntivo numa oração relativa de finalidade: <span class=\"greek\">ποῦ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κατάλυμα</span> <span class=\"greek\">ὅπου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πάσχα</span> <span class=\"greek\">φάγω</span>;, onde está o aposento em que comerei a Páscoa?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:14b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:11</a> (ver B-D-F § 378; Rob. 969). <span class=\"greek\">δ</span>. <span class=\"greek\">ὅπου</span> <span class=\"greek\">ἄν</span> (ou <span class=\"greek\">ἐάν</span>) com subjuntivo, onde quer que, sempre que (SIG 1218, 23; PEleph 1, 5 [311/310 a.C.]; POxy 484, 20; 1639, 20; TestAbr B 4 p. 109, 10f [Stone p. 66] <span class=\"greek\">ὅπου</span> <span class=\"greek\">ἄν</span> <span class=\"greek\">κοιμηθῇ</span>), com subjuntivo aoristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:10</a>; 9:18; 14:9 (ver KBeyer, Semitische Syntax im NT, ’62, 196), 14a. Com subjuntivo presente (e correspondência com <span class=\"greek\">ἐκεῖ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:28</a>. ⓑ De um lugar ao qual se chega por movimento, para onde (Soph., Trach. 40; X., An. 2, 4, 19, Cyr. 8, 3, 23 e outros em códices; Epict. 4, 7, 14; OdeSol 11:5; Jos., Ant. 16, 325). <span class=\"greek\">α</span>. Seguido de indicativo, relacionado com um «ali (para lá)» subentendido, onde (O. Wilck II, 1162, 5 <span class=\"greek\">ὅπου</span> <span class=\"greek\">θέλει</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:21f</a>; 13:33, 36; 14:4; 21:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:4</a>. <span class=\"greek\">β</span>. <span class=\"greek\">ὅπου</span> <span class=\"greek\">ἄν</span> (ou <span class=\"greek\">ἐάν</span>) com subjuntivo presente, onde quer que (POxy 728, 11; TestAbr B 2 p. 106, 8 [Stone p. 60] <span class=\"greek\">πορεύου</span> <span class=\"greek\">ὅπου</span> <span class=\"greek\">ἄν</span> <span class=\"greek\">βούλῃ</span>; com subjuntivo aoristo, Ruth 1:16; Tob 13:5 S; Jos., Ant. 6, 77), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.57\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:57</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:4</a>. ② Marcador de circunstância mais imediata ou expressão de uma premissa, onde, sentido figurado derivado de 1 (X., Cyr. 6, 1, 7): <span class=\"greek\">ὅπου</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔνι</span> <span class=\"greek\">Ἕλλην</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἰουδαῖος</span>, onde (isto é, aceitando a premissa relacionada à ideia da «nova pessoa») já não há grego nem judeu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:11</a>. Ou <span class=\"greek\">ὅπου</span> introduz oração subordinada indicadora das circunstâncias que resultam no conteúdo da oração principal seguinte (cf. Pr 26:20; EpArist 149; TestZeb 7:10): <span class=\"greek\">ὅπ</span>. <span class=\"greek\">διαθήκη</span>, <span class=\"greek\">θάνατον</span> <span class=\"greek\">ἀνάγκη</span> <span class=\"greek\">φέρεσθαι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαθεμένου</span>, onde há testamento, é necessário comprovar a morte de quem o fez, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:16</a>. <span class=\"greek\">ὅπ</span>. <span class=\"greek\">ἄφεσις</span> <span class=\"greek\">τούτων</span>, <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">κτλ</span>., onde há perdão dessas coisas, já não etc., 10:18. A oração principal pode empregar <span class=\"greek\">ἐκεῖ</span> para retomar o <span class=\"greek\">ὅπ</span>. da subordinada: onde …, ali, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:16</a>.—Usado para expressar circunstância oposta: <span class=\"greek\">ὅπου</span> <span class=\"greek\">ἄγγελοι</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">φέρουσιν</span> <span class=\"greek\">κρίσιν</span>, onde (isto é, numa situação em que) os anjos não pronunciam julgamento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:11</a>. ③ Marcador de causa ou razão, visto que, uma vez que (Hdt. 1, 68 e outros; Thu. 8, 96, 2; Chariton 5, 6, 10; 4 Macc 2:14; às vezes também na combinação <span class=\"greek\">ὅπου</span> <span class=\"greek\">γε</span>, como Dionys. Hal., Comp. Verb. 4; Jos., C. Ap. 2, 154), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:3</a>; 16:6.—Ao passo que, 1 Cl 43:1.—DELG s.v. <span class=\"greek\">πο</span>-. M-M.—Ver artigo <span class=\"greek\">οὗ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀπτάνομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀπτάνομαι</span> (novo presente formado por analogia com <span class=\"greek\">αἰσθάνομαι</span> [ver <span class=\"greek\">ὄπωπα</span> em DELG e Frisk; cf. B-D-F § 101 p. 54 sob <span class=\"greek\">ὁρᾶν</span>; Mlt-H. 214; 382]. Essa forma encontra-se em UPZ 62, 32 [161/160 a.C.]; PTebt 24, 5 [117 a.C.]; PGM 4, 3033; Herm Wr. 3, 2; 3 Km 8:8; Tob 12:19 BA.—SPsaltes, Gramm. der Byz. Chroniken 1913, 242; Schwyzer I 700), tornar-se visível a, aparecer, com <span class=\"greek\">τινί</span>, a alguém (B-D-F § 191, 1; 313; Rob. 820); acerca de Cristo ressuscitado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:3</a>.—HCadbury, JBL 44, 1925, 218f.—DELG s.v. <span class=\"greek\">ὄπωπα</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀπτασία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀπτασία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὀπτάζομαι</span>; passiva «ser visto»; Anth. Pal. 6, 210, 6; LXX, Just.; Hesychius; Leontius 8 p. 16, 12 = visão, fantasma [ver também lista de palavras p. 182a]). ① Evento de natureza transcendente que se imprime vividamente na mente, visão, aparição celestial, daquilo que uma divindade permite ao ser humano contemplar, seja a própria divindade, seja algo normalmente oculto aos mortais (Theod. Da 9:23; 10:1, 7f; Psellus p. 132, 19, fenômeno transcendente): <span class=\"greek\">ὀπτασίαι</span> (com <span class=\"greek\">ἀποκαλύψεις</span>) <span class=\"greek\">κυρίου</span>, visões do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:1</a> (ELombard, Les extases et les souffrances de l’apôtre Paul. Essai d’une interprétation de II Cor 12:1–10: RTP 36, 1903, 450–500). <span class=\"greek\">οὐράνιος</span> <span class=\"greek\">ὀπ</span>., visão celestial, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:19</a>. <span class=\"greek\">ὀπτασίαν</span> <span class=\"greek\">ὁρᾶν</span>, ter uma visão (Pel.-Leg. 18, 17), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:22</a>. Com genitivo daquilo que é visto: <span class=\"greek\">ὀπ</span>. <span class=\"greek\">ἀγγέλων</span> <span class=\"greek\">ὁρᾶν</span>, ter visão de anjos, 24:23 (ViZach 2 [p. 97, 4 Sch.]). <span class=\"greek\">ἡ</span> <span class=\"greek\">φανερωθεῖσα</span> <span class=\"greek\">ὀπ</span>., a visão manifestada, MPol 12:3. <span class=\"greek\">διὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὀπ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">γενομένην</span> <span class=\"greek\">Παύλῳ</span>, AcPl Ha 3,15. ② Estado experimentado por quem tem uma visão, êxtase, transe: <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀπτασίᾳ</span>, em transe, MPol 5:2.—DELG s.v. <span class=\"greek\">ὄπωπα</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀπτάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀπτάω</span> (<span class=\"greek\">ὀπτός</span>), aoristo <span class=\"greek\">ὤπτησα</span>, LXX; subjuntivo passivo, 3ª pessoa singular, <span class=\"greek\">ὀπτηθῇ</span> (Ar.) (Hom. e outros; PSI 402, 5 [III a.C.]; PLond III, 131, 115 p. 173; LXX; Jos., Ant. 1, 197; 3, 255; Ar. 4, 3; Just.), assar (assim Hdt. 8, 137; X., An. 5, 4, 29 <span class=\"greek\">ἄρτους</span> <span class=\"greek\">ὀπτῶντες</span>), MPol 15:2 <span class=\"greek\">ἄρτος</span> <span class=\"greek\">ὀπτώμενος</span>, pão assando.—DELG s.v. <span class=\"greek\">ὀπτό</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0257-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀπτός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀπτός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (Hom. e outros; papiros; Ex 12:8, 9; Jos., Ant. 3, 255), relativo à preparação de comida pelo fogo direto (em oposição a <span class=\"greek\">ἕψω</span>, «ferver/cozinhar»), assado, tostado, grelhado: <span class=\"greek\">ἰχθὺς</span> <span class=\"greek\">ὀπ</span>., peixe assado (Hippocr., Aff. 52 vol. VI p. 264 L. <span class=\"greek\">ἰχθύες</span> <span class=\"greek\">ὀπτοί</span>; Plut., Mor. 353d; PCairZen 66, 13; 16 [III a.C.]; PGiss 93, 6 [II d.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:42</a>.—Ver bibliografia s.v. <span class=\"greek\">μελίσσιος</span>.—DELG. M-M.</p></section></article>"};
